#!/usr/bin/env python3
# THE NUMBERS WALK, sitting 8 — THE SECOND CENSUS (2026-09-11; the owner: "Go" after the #132 rereads, on the ruling READ THEN COMPILE):
# THE READING of Numbers 26:1-65 — ONE append-only ledger logic/oral_triage/num_26_second_census_2026-09-11.md for the one draft that
# covers the chapter. The spine: Onkelos Numbers 26 whole (65; the export's 26:1 row carries 25:19's head, read at sitting 7) + the
# Sifrei on Numbers piska 132 BY POSITION (4 rows on 26:53-56; NO piska on 26:1-52 or 57-65 — computed on every head; the piska
# quick-looked at THE TENT, read whole here). COVERAGE COMPUTED; THE INK FACTS computed (census_ink.py, every fact an assert run by
# assert_driver.py — ten failures on the first typed pass, each a measurement); every quotation CUT by consonants (the misses collected,
# asserted empty); the roster rows built from the tokens; the rows in census_rows_onkelos.py and census_rows_sifrei.py. Sitting 7's form.
import sys, os
SP = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, SP)
from census_ink import *
from census_rows_onkelos import R
from census_rows_sifrei import S
assert not os.path.exists(OUT), f'ledger exists — append, never overwrite: {OUT}'
assert FAIL == [], FAIL
assert sorted(R) == SPAN and sorted(S) == [(132, r) for r in range(1, 5)], (len(R), sorted(S))

INK = {}
INK['shelf'] = ('- THE SHELF BY POSITION (computed on the export\'s rows): the Sifrei on Numbers has ONE piska on chapter 26 — 132, headed 26:53, FOUR rows on 26:53-56 (the apportionment), the next head 133 on 27:1 (the daughters, read at THE TENT); NO PISKA on 26:1-52 (the roster and its counts) or 26:57-65 — the census read on the translation alone, the walk\'s fifth such stretch; every head asserted between its neighbors. ROW 3\'S HEAD IS MISTYPED "26:25" in the export (the row quotes 26:55\'s "only by lot", its Hebrew opens with 26:55\'s first word) — the SIXTH mistyped head of the walk, placed by its quotation; TWO CITATIONS INSIDE THE ROWS ARE MISTYPED — row 1\'s "(Ibid. 59)" for 26:54\'s "to a man according to his numbers", row 3\'s "(Judges 15:13)" for Joshua 15:13 (the Hebrew row cites Judges 1:20 and Joshua 19 alone) — read to their verses (RESEARCH_LOG.md). THE PISKA WAS QUICK-LOOKED at THE TENT\'s daughters ("outside the span, not counted") and named in the inheritance docket\'s exam rows — neither a read of the rows: read whole here, fresh (credit guard 1). THE EXPORT\'S 26:1 ROW carries 25:19\'s three words at its head (the verse division that differs from the Masoretic, sitting 7\'s finding) — the head read there, the rest here.')
INK['parser'] = (f'- THE ENGINE\'S PARSER ON THE SECOND CENSUS (measured on cold_run_sequence.ink_numbers after 7b\'s rules): RIGHT AT EVERY NUMBER VERSE OF THE CHAPTER — seventeen: {", ".join(f"{c}:{v} {n[0]:,}" for (c, v), n in RIGHT.items())} — the twelve tribe counts, the two twenties, Korach\'s 250, the total 601,730 ("six hundred thousand AND A THOUSAND" — 1b\'s "and a thousand adds" at its second census) and the Levites\' 23,000 ("from a month old" no number); SILENT AND RIGHT at one homograph — 26:59\'s "their sister" (the feminine one\'s consonants); NO GAP on the chapter\'s own numbers — the first portion of the walk whose numbers the parser read whole (the census grammar taught at 1b reads its second seat); AND THE ARITHMETIC: the twelve counts SUM to the ink\'s 601,730 as chapter 1\'s twelve sum to 603,550 (computed at both); the deltas per tribe — {", ".join(f"{t} {C1[t]:,} → {C26[t]:,} ({"+" if d > 0 else "−"}{abs(d):,})" for t, d in DELTA.items())}; five fell (61,020), seven rose (59,200), the whole −1,820; the Levites 22,000 → 23,000; Simeon\'s fall 37,100 against the Peor plague\'s 24,000 — 13,100 the ink does not explain (the compile\'s labeled gap); Gad\'s 40,500 = Ephraim\'s first count, Asher\'s 53,400 = Naphtali\'s first — two repeats across the censuses; Reuben\'s 43,730 the one count not a round hundred (Gad\'s 45,650 was the first census\'s one); Judah the largest at both, Simeon the smallest here (Manasseh was, there); the order differs from chapter 1\'s by the Joseph pair alone (Manasseh before Ephraim).')
INK['frames'] = (f'- THE FRAMES AND THE REGISTER: three openings — 26:1 "the LORD SAID to Moses AND TO ELEAZAR" (the son for the father: "to Moses and to Eleazar" 26:1, 31:12, 32:2; "to Moses and to Aaron" eleven times in the book before), 26:3 "Moses and Eleazar the priest spoke [them]" (the object without its verb — the translation supplies "to count"), 26:52 "the LORD spoke to Moses" (alone; the land\'s law); 1:1 dated to the day, 26:1 undated — its time the half-verse 25:19; the register runs on {len(REG)} verses only ({", ".join(str(v) for c, v in REG)}) and is SILENT on {len(NOVERB)} — the roster carries no narrative verb: "were" six times, "said", "spoke" twice, "opened", "swallowed", "died" twice (Er and Onan; Nadab and Abihu), "bore", "was born" (computed on the morphology); "Moses and Eleazar" seven seats from 20:28 on, "Moses and Aaron" in this chapter only at 26:64 — the first roll recalled.')
INK['roster'] = (f'- THE ROSTER\'S FORM (computed on the tokens): "family of" SEVENTY-EIGHT times — chapter 1 has the word NOT ONCE (it counts "by the number of names"; chapter 3 has nine); the family form is the article + the name + the gentilic yod ("the Hanochite") — sixty-eight such forms, sixty-five family gentilics once the three tribe-gentilic summaries are set aside, sixty-three distinct (Zerah\'s is Simeon\'s AND Judah\'s, Dan\'s one family named twice) and ONE family name without the yod, "the family of THE IMNAH" (26:44); FIFTY-SEVEN FAMILIES in the twelve tribes ({", ".join(f"{t} {n}" for t, n in NFAM.items() if t != "Levi")}) and EIGHT in Levi (three sons + five); "by their families" fifteen verses; the twelve SUMMARIES in three forms — the tribe-gentilic (the Reubenite, the Simeonite, the Zebulunite, Dan\'s "all the families of the Shuhamite"), "the sons of" (Gad, Ephraim, Benjamin, Asher), the bare name (Judah, Issachar, Manasseh, Naphtali); THE COUNT-WORD in eleven summaries — SIMEON\'S ALONE WITHOUT IT (26:14 gives the number bare); the count-root sixteen tokens in six forms; THREE TRIBE-HEADS OPEN THEIR FIRST NAME BARE of the preposition — Hanoch (26:5), Tola (26:23), Iezer (26:30) — the other eleven with "of"; "Reuben the firstborn of Israel" PLENE at 26:5, DEFECTIVE at 1:20 and Genesis 46:8; "begot" once in full (Machir, 26:29) and once short (Kohath, 26:58 — the Torah\'s one defective token); the deepest line Joseph → Manasseh → Machir → Gilead → Hepher → Zelophehad → the daughters (27:1\'s lineage read upward).')
INK['genesis46'] = ('- GENESIS 46 AGAINST NUMBERS 26 — THE DESCENT ROSTER AGAINST THE CENSUS ROSTER, NAME BY NAME (computed on every token of both): FIVE Genesis names ABSENT — Simeon\'s OHAD, Benjamin\'s BECHER, GERA and ROSH, Asher\'s ISHVAH (each with its Genesis seat and its Exodus 6 or Chronicles kin, none in the census); NINE RENAMED — Jemuel → Nemuel, Zohar → Zerah, Ziphion → ZEPHON (the word "to the north"), Ezbon → Ozni, Iob → Jashub, Ehi → Ahiram, Muppim → Shephupham, Huppim → Hupham, Hushim → Shuham (each old form at its Genesis seat alone, each new form at its census seat alone; 1 Chronicles 4:24 and 7:1 keep the census\'s forms); TWO MOVED DOWN A GENERATION — Ard and Naaman, Benjamin\'s sons at Genesis 46:21, Bela\'s sons at 26:40 (Genesis 46:7\'s "his sons and his sons\' sons" the roster\'s own license); a BECHER of Ephraim (26:35) where Genesis had a Becher of Benjamin; Reuben\'s four, Zebulun\'s three, Naphtali\'s four, Levi\'s three, Judah\'s seven IDENTICAL, and "Er and Onan died in the land of Canaan" VERBATIM at both rosters — the only death-notice among the twelve; Joseph\'s TWELVE families (Manasseh 8, Ephraim 4) have no Genesis 46 name at all (46:20 names the two sons); Benjamin\'s sons TEN at Genesis 46, FIVE here, THREE at 1 Chronicles 7:6, FIVE others at 8:1-2 — four rosters, four counts; Dan ONE son at both, "sons" said of one, the second-largest tribe from him (64,400).')
INK['korach'] = ('- KORACH RECALLED (computed): "the earth opened its mouth and swallowed them" — 16:32\'s clause at two seats alone (26:10; Deuteronomy 11:6 says "gaped", Psalm 106:17 "opened and swallowed Dathan"); 26:10 adds "AND KORACH" to the swallowed and sets him "in the death of the company, when the fire consumed the 250" — one verse, both deaths (the tape\'s CK4 open on his death-mode since sitting 5b; the exam\'s Sanhedrin 110a); "and they became A SIGN" — the noun\'s Torah four: the LORD-is-my-banner (Exodus 17:15), the serpent\'s POLE (21:8, 9), this; "who STROVE... when they strove" — the strive-verb\'s two tokens at 26:9 alone in the Torah (Psalm 60:2\'s heading its kin); "THE CALLED OF THE CONGREGATION" — 1:16\'s title, and the two seats are a written-and-read pair REVERSED (the store\'s two adjacent tokens at each verse, the unpointed one the written form; the Tanakh DB one form per seat); "in the company of Korach" here and in the daughters\' plea (27:3); "but the sons of Korach DID NOT DIE" one seat — eleven psalms "for the sons of Korach"; a second NEMUEL (Eliab\'s son of Reuben, 26:9) beside Simeon\'s (26:12); the family "of Korah" in the Levite roster (26:58) where Izhar\'s is not.')
INK['women'] = ('- THE WOMEN AND THE PRIESTS (computed): EIGHT WOMEN NAMED in the census chapter — Zelophehad\'s five (26:33, their FIRST seat in the ink, "had no sons, only daughters" the case\'s premise as a census row; 26:33\'s order = 27:1\'s = Joshua 17:3\'s, 36:11 reorders), SERAH daughter of Asher (26:46 — one name on three rosters: Genesis 46:17, here, 1 Chronicles 7:30), JOCHEBED (26:59 — "daughter of Levi, whom SHE BORE — her — to Levi IN EGYPT": the verb perfect feminine with the object and NO SUBJECT, the mother unnamed, "bore her" the Bible\'s one seat; "in Egypt" the datum the seventy of Genesis 46:26-27 turn on — 66, then 70; the tape\'s CJ3b open by one; the exam\'s Bava Batra 123a), MIRIAM "their sister" (her one seat in a roster; Aaron before Moses as at Exodus 6:20); Elisheba dropped from 26:60\'s passive "there were born to Aaron" (Exodus 6:23 named her); Nadab and Abihu\'s death at 26:61 is 3:4 with four clauses dropped (before the LORD; in the wilderness of Sinai; they had no sons; Eleazar and Ithamar served) and "when they brought near" spelled plene; "strange fire" three seats.')
INK['land'] = ('- THE LAND BY COUNT AND BY LOT (computed): "to these" (the counted) "by THE NUMBER OF NAMES" — the FIRST census\'s counting phrase (1:2, 18, 20, 22, 24, 34; 3:43) applied to the land; "to the many increase, to the few diminish" one seat singular (33:54 plural, 35:8 for the Levite cities); "to a man according to his counted" — the summaries\' word in the singular; "ONLY by LOT" — the lot-word\'s Torah seats Yom Kippur\'s two goats (Leviticus 16:8-10, four tokens) and the land (26:55, 56, 33:54, 34:13, 36:2 — eleven tokens in eight verses), Joshua\'s twenty-four verses the run (14:2 quoting 34:13\'s "nine tribes and the half-tribe"), sixty-five in the Bible; "by the names of the tribes of their fathers", "BY THE MOUTH OF THE LOT", "between many and few" one seat each — the lot has a mouth, Onkelos keeps it, Joshua 19:50 names its owner; "shall be divided" 26:53, 56, Amos 7:17, Psalm 68:13; "as an inheritance" 26:53, 34:2, 36:2; "only" forty-one Torah tokens.')
INK['levites'] = ('- THE LEVITES (computed): three sons and FIVE families (Libni, Hebron, Mahli, Mushi, KORAH) where 3:17-20 and Exodus 6:16-19 gave eight — Shimei, Amram, Izhar, Uzziel have no family token in the chapter (Amram a person by the begetting), and 3:27\'s four Kohathite families are two here; 23,000 "from a month old and upward" (the Levite formula\'s eight seats) against 3:39\'s 22,000; "they were not counted among the children of Israel" at the three census summaries (1:47, 2:33, 26:62); "for no inheritance was given them among the children of Israel" one seat — 18:20-24\'s rule, the two reasons chained by two "for"s, the Sifrei\'s proof-texts (132:1) the ink\'s own sentence.')
INK['close'] = ('- THE CLOSE (computed): 26:63 and 26:64 are ONE SENTENCE TWICE — "these are the counted of Moses and ELEAZAR the priest who counted the children of Israel IN THE PLAINS OF MOAB BY THE JORDAN OF JERICHO" / "and among these there was NOT A MAN of the counted of Moses and AARON the priest who counted the children of Israel IN THE WILDERNESS OF SINAI" — the priest and the place the only deltas: the membership predicate that no name is on both rolls (the ark\'s "all that came out" at national scale); "in the plains of Moab" nine seats, "by the Jordan of Jericho" seven (all Numbers), "in the wilderness of Sinai" nine; 26:65 "they shall surely die in the wilderness" (one seat; 14:35\'s decree, 14:29\'s "all your counted ones from twenty years old and upward" naming the first roll in the sentence), "and there was not left of them a man" (the locusts\' "nothing green was left", Exodus 10:15, the Torah\'s other seat), "EXCEPT CALEB SON OF JEPHUNNEH AND JOSHUA SON OF NUN" — 14:30\'s last seven words VERBATIM; Deuteronomy 2:14-16 the retelling (38 years "until all the generation of the men of war was consumed", the parser reading 38).')
INK['translation'] = ('- THE TRANSLATION\'S OWN WORDS, cut from the shelf\'s bytes: "lift the head" → RECEIVE THE COUNT (26:2); "spoke [them]" → said TO COUNT them (26:3 — the verb supplied); "family of" → SEED-GROUP at every seat, the gentilic dropped (the Hanochite → of Hanoch); "three and forty thousand" → FORTY AND THREE (26:7, and every count reversed to tens-first); "the called of the congregation" → THE SUMMONED, "who strove" → who GATHERED (26:9); "a sign" (the pole-word) → a SIGN (the sign-word, 26:10); "had no sons, only daughters" kept (26:33); Serah spelled with a samekh (26:46); "and a thousand" → "and ONE thousands" (26:51); "shall be divided" → תתפלג (26:53, 56); "only" → BUT (26:55); "by the mouth of the lot" KEPT (26:56); "his inheritance" → THEIR inheritance for the many and the few (26:54, 56 — the man\'s "his" kept singular); "whom she bore her" KEPT SUBJECTLESS (26:59); "there were born" → was born (26:60); "strange fire" → FOREIGN fire (26:61); "were not counted" → were not counted, "no inheritance was given" kept (26:62); "the counted" → the COUNTS (26:63-64); "they shall surely die" kept doubled (26:65).')
def register_line(c, lo, hi): return f'- THE REGISTER: {register(c, lo, hi)} — the narrative verbs of the chapter, each glossed by the snapshot store\'s own words.gloss (the narrative-past "and he did" form, the register test); the roster\'s fifty-two verses carry none.'

TESTING = 'THE TESTING SHELF routed to Step 5 (the compile sitting\'s docket, per gap): Bava Batra 117a-122b (the division of the land — to the exodus generation or the entrants, R. Yoshiyah / R. Yonatan / R. Shimon b. Elazar; "the dead inherit the living" and Rebbi\'s parable; Joshua and Caleb\'s portions; the lot and the Urim, "I am the lot of Zebulun"; the estimate — a kor\'s-space against a seah\'s-space; the protesters = Korach\'s 250), 123a (Jochebed born between the walls — the seventieth), 143b ("the sons of Dan: Hushim" — "sons" of one); Sotah 12a (Jochebed\'s birth and age), 13a (Serah and Joseph\'s coffin); Sanhedrin 110a (Korach — swallowed, burned, or neither; the sons of Korach and their place in Gehenna), 108a? no; Megillah 14a (the sons of Korach); Mishnah Bava Batra 8:1-2 (the order of inheritance — the daughters\' plea\'s home, read at THE TENT), 7:1-4 (the field\'s measures); Yoma 73b (the Urim at the division); Bava Batra 121b-122a (the decree on the men of war, not the women — 26:64 "not a MAN"); Seder Olam 9-10 (the year of the census — the fortieth, after Aaron\'s death); Sifrei Zuta and Numbers Rabbah outside scope.'

verses = list(range(1, 66)); c = 26
sif_cites = [f'Sifrei Bamidbar 132:{r}' for r in range(1, 5)]
cites = [f'Onkelos Num {c}:{v}' for v in verses] + sif_cites
N_ALL = len(cites); NS = len(sif_cites)
cnt = Counter(R[(c, v)][0] for v in verses); scnt = Counter(S[(132, r)][0] for r in range(1, 5))
hdr = (f'# Numbers 26:1-65 derivation — Onkelos + the Sifrei on Numbers as the spine (its piska found BY POSITION), '
       f'THE NUMBERS WALK sitting 8 — THE SECOND CENSUS, {TITLE} ({DATE}; the owner: "Go" after the #132 rereads, on the ruling NUMBERS IN ORDER FROM 1:1 and READ THEN COMPILE). '
       f'DECLARED (THE_STEPS Step 2, the spine default of 2026-08-27, read at the PARASHAH GRAIN — speed ruling (a): the portion Pinchas opens at 25:10, read with Balak\'s last draft on the draft\'s-grain rule; this draft is chapter 26 whole; the next draft, chapter 27, is FROZEN at THE TENT and skipped when reached): scope = Onkelos Numbers 26:1-65 (65 verses, fresh; the export\'s 26:1 row carries 25:19\'s head, read at sitting 7) '
       f'+ the Sifrei on Numbers piska 132 BY POSITION ({NS} rows at the shelf\'s row grain — the one piska between 131 on 25:1 and 133 on 27:1, its head on 26:53, its rows on 26:53-56; row 3\'s head mistyped "26:25" in the export and two citations inside the rows mistyped, read to their verses; the piska quick-looked at THE TENT and read whole here; NO piska on 26:1-52 or 26:57-65 — computed on every head). {TESTING} OUTSIDE DECLARED SCOPE, enumerated and unread (the shelf\'s other works on Numbers, {len(outside)} directories): {", ".join(outside)}.\n\n')
body = f'## Sifrei Bamidbar piska 132 ({NS} rows, read whole — the head by position: 132 on 26:53; the rows on 26:53, 54, 55 (the export\'s head "26:25" placed by its quotation), 55-56)\n'
for r in range(1, 5):
    verdict, prose = S[(132, r)]
    body += f'- Sifrei Bamidbar 132:{r} — {verdict}. {prose}\n'
body += f'\n## Onkelos Numbers 26:1-65 (65 verses, read whole)\n'
for v in verses:
    verdict, prose = R[(c, v)]
    body += f'- Onkelos Num {c}:{v} — {verdict}. {prose}\n'
body += '\n## The ink beside the shelf (computed by this script from the Tanakh DB, the snapshot store and the shelf — never recited)\n'
for k in ('shelf', 'parser', 'frames', 'roster', 'genesis46', 'korach', 'women', 'land', 'levites', 'close', 'translation'): body += INK[k] + '\n'
body += register_line(c, 1, 65) + '\n'
CROWNS = [
 '- THE MEMBERSHIP PREDICATE, WRITTEN AS TWO ROLLS: 26:63 and 26:64 are one sentence twice, the priest\'s name and the place the only deltas — "not a man of the counted of Moses and Aaron... in the wilderness of Sinai" is on the roll of "Moses and Eleazar... in the plains of Moab": the ark\'s "all that came out of the ark" (Genesis 9:10) at national scale, a table checked against a table, and the first census\'s own counting phrase "by the number of names" returned as the LAND\'s formula (26:53) — the roll that counted the host sizes the portions (computed).',
 '- THE PARSER READ THE CHAPTER WHOLE: seventeen number verses right, the twelve counts summing to the ink\'s 601,730 as chapter 1\'s sum to 603,550 — the first portion of the walk with no new gap on its own numbers; the deltas the compile will check are the ink\'s: five tribes fell (61,020), seven rose (59,200), the whole −1,820, and SIMEON\'S 37,100 is 13,100 MORE than the Peor plague\'s 24,000 could take even if every dead man were his — a gap the ink leaves and the compile will label (computed).',
 '- SIMEON\'S SUMMARY ALONE LACKS THE COUNT-WORD: eleven summaries say "by their counted ones" or "and their counted ones" — 26:14 gives the tribe that fell its number bare, "these are the families of the Simeonite: twenty-two thousand two hundred" (computed on the sixteen tokens of the root); and the summaries come in three forms — the gentilic, "the sons of", the bare name.',
 '- GENESIS 46 AGAINST NUMBERS 26, NAME BY NAME: five names absent (Ohad, Becher, Gera, Rosh, Ishvah), nine renamed (Jemuel/Nemuel, Zohar/Zerah, Ziphion/Zephon — the north-word, Ezbon/Ozni, Iob/Jashub, Ehi/Ahiram, Muppim/Shephupham, Huppim/Hupham, Hushim/Shuham), two moved down a generation (Ard and Naaman, Benjamin\'s sons made Bela\'s — Genesis 46:7\'s "his sons and his sons\' sons" the license), a Becher who changes tribes, Er and Onan\'s death-clause verbatim at both, and Joseph\'s twelve families with no Genesis name at all; Benjamin\'s sons ten, five, three, five across four rosters; Dan\'s one "sons" — all computed on the tokens of both chapters.',
 '- THE FAMILY FORM: "family of" seventy-eight times where chapter 1 has it not once; sixty-eight forms of the article + the name + the gentilic yod, and ONE without the yod, "the family of THE IMNAH" (26:44); fifty-seven families in the twelve tribes, eight in Levi; three heads open their first name bare (Hanoch, Tola, Iezer); "Reuben the firstborn" plene here and defective at 1:20 (computed).',
 '- KORACH NAMED AMONG THE SWALLOWED AND SET AT THE FIRE: 26:10 repeats 16:32\'s "the earth opened its mouth and swallowed them" (the two seats alone) and adds "AND KORACH... in the death of the company, when the fire consumed the 250" — the ink\'s own two-death sentence for the tape\'s open CK4; "and they became a SIGN" is the serpent\'s POLE-word (21:8-9; Exodus 17:15 the banner) — the Torah\'s four; "who STROVE" the verb\'s one Torah verse; "the called of the congregation" 1:16\'s written-and-read pair REVERSED; "but the sons of Korach did not die" — eleven psalms\' heading (computed).',
 '- EIGHT WOMEN IN A CENSUS OF MEN: Zelophehad\'s five named at 26:33 BEFORE the plea — "had no sons, only daughters" is a row of the census the case of 27 queries, and 27:1\'s lineage is 26:29-33 read upward; Serah on three rosters (Genesis 46:17, 26:46, 1 Chronicles 7:30); Jochebed "whom SHE bore — her — to Levi IN EGYPT" — the verb without its subject, the mother unnamed, "in Egypt" the datum the seventy of Genesis 46 turn on (the tape\'s CJ3b open by one since the Joseph sitting; the exam\'s Bava Batra 123a); Miriam "their sister" in a roster once (computed).',
 '- THE LEVITE FAMILIES FIVE FOR EIGHT — KORAH\'S IN, IZHAR\'S OUT: 26:58 names Libni, Hebron, Mahli, Mushi and KORAH where 3:18-20 named Libni, Shimei, Amram, Izhar, Hebron, Uzziel, Mahli, Mushi — the grandson\'s name for the line "that did not die" (26:11), the four others without a token in the chapter; "Kohath BEGOT Amram" spelled short, the Torah\'s one defective "begot"; 23,000 for 22,000; "not counted... for no inheritance was given them" — the Sifrei\'s two proof-texts (18:20, 24) are the ink\'s own two "for"s at 26:62 (computed).',
 '- THE LAND BY COUNT AND BY LOT: "to the many increase, to the few diminish" (26:54; 33:54 plural; 35:8 for the Levite cities), "to a man according to his counted" — the summaries\' word in the singular; "ONLY by lot" — the lot-word\'s Torah seats Yom Kippur\'s goats and the land (eleven tokens), Joshua\'s twenty-four verses the run; "BY THE MOUTH OF THE LOT" — the lot has a mouth, Onkelos keeps it, Joshua 19:50 names its owner; the Sifrei\'s four rows (the inclusion read wide and four exclusions by four verses; the four-way dispute on WHO — "the dead inherit the living"; "only" excluding Joshua and Caleb, the same two 26:65 excepts; the estimate, a kor\'s-space against a seah\'s-space) with the sixth mistyped head and two mistyped citations (computed, recorded).',
 '- 3:4 SHORTENED AND 26:2 SHORTENED: Nadab and Abihu\'s death-notice drops four clauses of 3:4 (before the LORD; in the wilderness of Sinai; no sons; Eleazar and Ithamar\'s service) and spells "when they brought near" plene; the census command drops five clauses of 1:2-3 (by their families; by the number of names; every male by their polls; you shall count them by their hosts; you and Aaron) — the second seat\'s delta at two more seats (M-23\'s form; computed by set difference).',
 '- THE TRANSLATION SUPPLIES THE MISSING VERB AND DROPS THE GENTILIC: 26:3\'s "Moses and Eleazar spoke [them]" — the object marker with no counting verb — becomes "said to COUNT them"; "lift the head" becomes "receive the count"; "the family of the Hanochite" becomes "the seed-group of Hanoch" at sixty-five seats; the subjectless "whom she bore her" is kept subjectless; "by the mouth of the lot" is kept with its mouth; every count is reversed to tens-first (cut from the shelf\'s bytes).',
]
body += '\n## The finds (this ledger\'s crowns)\n' + '\n'.join(CROWNS) + '\n'
body += (f'\n## CITE INDEX — every source opened, each fully named\n(one name per line; coverage COMPUTED against the shelf by the ledger script write_census_ledger.py: Onkelos Numbers 26:1-65 65 verses — missing 0, extra 0; the Sifrei on Numbers piska 132, {NS} rows at the shelf\'s own row count — missing 0, extra 0)\n')
body += '\n'.join(cites) + '\n'
body += f'(65 Onkelos verses fresh + {NS} Sifrei Bamidbar rows fresh = {N_ALL} sources in this ledger.)\n\n'
body += (f'**read: {N_ALL} of {N_ALL} — COMPLETE** (65 Onkelos verses and {NS} Sifrei rows opened and verdicted this sitting at the shelf\'s row grain, coverage computed by script — missing 0, extra 0; '
         f'verdicts MATERIAL {cnt["MATERIAL"]} Onkelos, CONTEXT {cnt["CONTEXT"]} Onkelos, MATERIAL {scnt["MATERIAL"]} Sifrei, CONTEXT {scnt["CONTEXT"]} Sifrei — the counts the script\'s own Counter measured)\n')
assert FAIL == [], FAIL
open(OUT, 'w', encoding='utf-8').write(hdr + body)
print(f'wrote {OUT}: {N_ALL} sources, Onkelos MATERIAL {cnt["MATERIAL"]} / CONTEXT {cnt["CONTEXT"]}; Sifrei {NS} rows MATERIAL {scnt["MATERIAL"]} / CONTEXT {scnt["CONTEXT"]}; the parser right {len(RIGHT)}, homographs silent {len(HOMOGRAPH)}, gaps {len(GAPS)}')
